"""Owner 2026-10-27 19:31: make the EMA200 w8v8 and EMA100 v7 surfaces calculable from the front with the SIMULATION vote parameters, IN PLACE
(no new surfaces, rows unchanged). As on EMA500 (vote_threshold / own_vote_threshold): one optional column per mutually exclusive vote variant,
its value = the vote threshold, its option inserts its own weighted_vote_setup with the column bound to /params/threshold.
runs.csv: new columns right after w8_vote: v6_vote ('1' where w8_vote=6), v7_threshold ('1.75' where 7), v8_threshold ('1.75' where 8); w8_vote kept as data.
manifest: w8_vote option + dimension replaced by those; v6 keeps the not-calculable placeholder (premium voter not in Engine).
Every file edited IN PLACE (same inode), backups *.pre_v7v8_<ts>.*. Usage: python3 apply_v7v8.py <analysis dir> [--dry] [--plan] (--plan: after the change, ask Research 8095 calculate-plan for one row per variant; read-only)"""
import sys, os, csv, json, gzip, base64, shutil, copy, datetime as dt
AN = sys.argv[1]; DRY = '--dry' in sys.argv; TS = dt.datetime.now(dt.timezone.utc).strftime('%Y%m%dT%H%M%SZ')
B64 = {'v7': '', 'v8': ''}
CFG = {n: json.loads(gzip.decompress(base64.b64decode(s))) for n, s in B64.items()}
TH = 1.75
SURF = [(tk, 'ema200', 'width_x_untouched_x_stop_x_ratio_x_touch_x_w8v8_6d') for tk in ('BTCUSDT.P', 'ETHUSDT.P', 'SOLUSDT.P')] + \
       [(tk, 'ema100', 'width_x_untouched_x_stop_x_ratio_x_touch_x_v7_6d') for tk in ('BTCUSDT.P', 'ETHUSDT.P', 'SOLUSDT.P')]
NEW = {'6': ('v6_vote', '1'), '7': ('v7_threshold', '1.75'), '8': ('v8_threshold', '1.75')}
LABEL = {'v6_vote': 'Голос W8 вариант 6 (только просмотр: фильтра премии нет в Engine, пересчёт невозможен)',
         'v7_threshold': 'Голос W8 вариант 7, порог (веса из симуляции; считается Engine)',
         'v8_threshold': 'Голос W8 вариант 8 = 7 + наклоны EMA, порог (веса из симуляции; считается Engine)'}
PLAN = '--plan' in sys.argv
def plan(M, d):
    import urllib.request
    dims = M['result_schema']['dimensions']; rows = list(csv.DictReader(open(f'{d}/runs.csv', newline='', encoding='utf-8'))); req = []
    for want in ('', 'v6_vote', 'v7_threshold', 'v8_threshold'):
        cand = [r for r in rows if (r.get(want) if want else not any(r.get(c) for c in NEWC)) and not r['candidate_id'].endswith('-tr')]
        if cand: r = cand[len(cand) // 2]; req.append({'coords': {x['id']: float(r[x['column']]) for x in dims if r.get(x['column'], '') != ''}})
    body = json.dumps({'rows': req}).encode()
    q = urllib.request.Request(f"http://127.0.0.1:8095/api/research/experiments/{M['experiment_id']}/runs/calculate-plan", data=body, headers={'Content-Type': 'application/json'})
    try:
        out = json.loads(urllib.request.urlopen(q, timeout=120).read())
    except Exception as e:
        out = {'error': str(e), 'body': getattr(e, 'read', lambda: b'')()[:500].decode('utf-8', 'replace')}
    print('  PLAN', M['experiment_id'], json.dumps([x['coords'] for x in req], ensure_ascii=False), json.dumps(out, ensure_ascii=False)[:1500], flush=True)
NEWC = ('v6_vote', 'v7_threshold', 'v8_threshold')
def write_inplace(path, text):
    ino = os.stat(path).st_ino
    with open(path, 'r+', encoding='utf-8', newline='') as fh: fh.seek(0); fh.write(text); fh.truncate()
    assert os.stat(path).st_ino == ino
for tk, ema, test in SURF:
    d = f'{AN}/{tk}/{ema}/{test}'
    if not os.path.isdir(d): print('MISSING', d); continue
    M = json.load(open(f'{d}/manifest.json', encoding='utf-8')); mt = M['materialize']
    print(tk, ema, 'template ema_stack_episode', mt['strategy_template']['raw_spec'].get('ema_stack_episode'), 'experiment', M.get('experiment_id'), flush=True)
    if any(o['column'] in ('v7_threshold', 'v8_threshold') for o in mt['options']):
        print('ALREADY DONE', d)
        if PLAN: plan(M, d)
        continue
    with open(f'{d}/runs.csv', newline='', encoding='utf-8') as fh: rows = list(csv.reader(fh))
    H = rows[0]; iv = H.index('w8_vote'); vals = {r[iv] for r in rows[1:]}; assert vals <= {'', '6', '7', '8'}, vals
    newc = [NEW[k][0] for k in ('6', '7', '8') if k in vals]
    H2 = H[:iv + 1] + newc + H[iv + 1:]
    out = [H2] + [r[:iv + 1] + [(NEW[r[iv]][1] if r[iv] in NEW and NEW[r[iv]][0] == c else '') for c in newc] + r[iv + 1:] for r in rows[1:]]
    old = [o for o in mt['options'] if o['column'] == 'w8_vote']; assert len(old) == 1, [o['id'] for o in mt['options']]
    opts = [o for o in mt['options'] if o['column'] != 'w8_vote']
    for c in newc:
        if c == 'v6_vote':
            it = copy.deepcopy(old[0]['insert']['item']); it['instance_id'] = 'w8_vote_v6'
            it['params'] = {'reason': 'Calculate не поддерживается: в голосе 6 есть фильтр премии (PS_R), его нет в Engine. Engine отклоняет эту спецификацию.'}
            opts.append({'id': 'v6_vote', 'column': 'v6_vote', 'insert': {'path': '/raw_spec/setups', 'item': it}})
        else:
            it = copy.deepcopy(CFG[c[:2]]); it['instance_id'] = 'w8_vote_' + c[:2]
            opts.append({'id': c, 'column': c, 'insert': {'path': '/raw_spec/setups', 'item': it,
                         'bindings': [{'column': c, 'path': '/params/threshold', 'type': 'number'}]}})
    mt['options'] = opts
    dims = M['result_schema']['dimensions']; j = [k for k, x in enumerate(dims) if x.get('column') == 'w8_vote']; assert len(j) == 1
    dold = dims[j[0]]
    nd = [dict({k: v for k, v in dold.items() if k not in ('id', 'column', 'label', 'values', 'unit')}, id=c, label=LABEL[c], column=c,
               unit='вкл' if c == 'v6_vote' else 'порог', optional=True, values=[1] if c == 'v6_vote' else [TH]) for c in newc]
    M['result_schema']['dimensions'] = dims[:j[0]] + nd + dims[j[0] + 1:]
    for v in M['result_schema'].get('view', []):
        if 'w8_vote' in v.get('controls', []):
            k = v['controls'].index('w8_vote'); v['controls'] = v['controls'][:k] + newc + v['controls'][k + 1:]
    M.setdefault('history', []).append({'at': dt.datetime.now(dt.timezone.utc).isoformat(timespec='seconds'),
        'event': 'w8_vote split into one optional column per variant (' + ', '.join(newc) + '); v7/v8 options insert the vote with simulation curves, exponents and theta 1.75 (calculable by Engine); rows unchanged'})
    s = json.dumps(M, indent=2, ensure_ascii=False); json.loads(s)
    cnt = {c: sum(1 for r in out[1:] if r[H2.index(c)]) for c in newc}
    print(tk, ema, 'rows', len(rows) - 1, 'new columns', cnt, 'options', [o['id'] for o in opts], 'dims', [x['id'] for x in M['result_schema']['dimensions']], flush=True)
    if DRY: continue
    shutil.copy2(f'{d}/manifest.json', f'{d}/manifest.pre_v7v8_{TS}.json'); shutil.copy2(f'{d}/runs.csv', f'{d}/runs.pre_v7v8_{TS}.csv')
    import io; buf = io.StringIO(); csv.writer(buf, lineterminator='\n').writerows(out)
    write_inplace(f'{d}/runs.csv', buf.getvalue()); write_inplace(f'{d}/manifest.json', s)
    print('  written', os.path.getsize(f'{d}/runs.csv'), os.path.getsize(f'{d}/manifest.json'), flush=True)
    if PLAN: plan(M, d)
